<?php
require __DIR__ . '/app.php'; require_admin();
$error=''; $saved=isset($_GET['saved']); $search=trim($_GET['search']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf(); $id=(int)($_POST['ticket_id']??0); $status=$_POST['status']??''; $note=trim($_POST['admin_note']??''); $search=trim($_POST['search']??''); $allowed=['รอดำเนินการ','กำลังดำเนินการ','เสร็จสิ้น','ยกเลิก'];
    if(!in_array($status,$allowed,true)) $error='สถานะที่เลือกไม่ถูกต้อง';
    else try{$stmt=db()->prepare('UPDATE repair_tickets SET status=?,admin_note=? WHERE id=?');$stmt->bind_param('ssi',$status,$note,$id);$stmt->execute();$stmt->close();header('Location: staff_dashboard.php?search='.urlencode($search).'&saved=1');exit;}catch(Throwable $e){$error='บันทึกข้อมูลไม่สำเร็จ';}
}
$conn=db();
if($search!==''){$like='%'.$search.'%';$stmt=$conn->prepare('SELECT t.*,u.name,u.lastname,u.department FROM repair_tickets t JOIN users u ON u.id=t.user_id WHERE t.student_id LIKE ? OR t.ticket_code LIKE ? ORDER BY t.created_at DESC LIMIT 100');$stmt->bind_param('ss',$like,$like);}
else{$stmt=$conn->prepare('SELECT t.*,u.name,u.lastname,u.department FROM repair_tickets t JOIN users u ON u.id=t.user_id ORDER BY t.created_at DESC LIMIT 100');}
$stmt->execute();$tickets=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
page_head('จัดการงานแจ้งซ่อม','staff'); ?>
<section class="page-intro"><div><p class="eyebrow">IT TEAM WORKSPACE</p><h1>จัดการงานซ่อม</h1><p>ค้นหา Ticket และอัปเดตความคืบหน้าให้ผู้แจ้งทราบ</p></div><div class="summary-box"><b><?=count($tickets)?></b><span>รายการ<?= $search ? 'ที่ค้นพบ' : 'ล่าสุด' ?></span></div></section>
<section class="panel staff-search"><form method="get"><label for="search">ค้นหาด้วย Ticket หรือรหัสนักศึกษา</label><div class="search-row"><input id="search" name="search" value="<?=e($search)?>" placeholder="เช่น RIETC-A7K2P หรือรหัสนักศึกษา"><button class="button">ค้นหา</button><?php if($search): ?><a class="button button-light" href="staff_dashboard.php">ล้าง</a><?php endif; ?></div></form></section>
<?php if($saved): ?><div class="success-banner">บันทึกการอัปเดตเรียบร้อยแล้ว</div><?php endif; ?><?php if($error): ?><div class="alert"><?=e($error)?></div><?php endif; ?>
<section class="staff-list"><?php if(!$tickets): ?><div class="empty-state"><span>⌕</span><h3>ไม่พบรายการ</h3><p>ลองตรวจสอบคำค้นหาหรือกลับมาดูภายหลัง</p></div><?php else: foreach($tickets as $t): ?><article class="panel staff-card"><div class="staff-card-head"><div><small><?=e($t['name'].' '.$t['lastname'])?> · <?=e($t['student_id'])?></small><h2><?=e($t['ticket_code'])?></h2><p><?=e($t['department'])?></p></div><span class="status <?=e(status_class($t['status']))?>"><?=e($t['status'])?></span></div><div class="staff-details"><div><small>สถานที่</small><p><?=e($t['building'])?> · <?=e($t['floor'])?></p></div><div><small>เบอร์ติดต่อ</small><p><?=e($t['contact_phone'])?></p></div><div><small>วันที่แจ้ง</small><p><?=e($t['created_at'])?></p></div><div class="wide"><small>อาการ</small><p><?=nl2br(e($t['description']))?></p></div></div><?php if($t['image_path']): ?><a href="<?=e($t['image_path'])?>" target="_blank" rel="noopener"><img class="ticket-image" src="<?=e($t['image_path'])?>" alt="ภาพประกอบการแจ้งซ่อม"></a><?php endif; ?><form class="update-box" method="post"><?=csrf_field()?><input type="hidden" name="ticket_id" value="<?=(int)$t['id']?>"><input type="hidden" name="search" value="<?=e($search)?>"><div class="two-col"><label>สถานะ<select name="status"><?php foreach(['รอดำเนินการ','กำลังดำเนินการ','เสร็จสิ้น','ยกเลิก'] as $s): ?><option value="<?=e($s)?>" <?=$s===$t['status']?'selected':''?>><?=e($s)?></option><?php endforeach; ?></select></label><label>หมายเหตุจากทีม IT<textarea name="admin_note" rows="2" placeholder="บันทึกสิ่งที่ตรวจพบหรือขั้นตอนถัดไป"><?=e($t['admin_note'])?></textarea></label></div><button class="button button-small">บันทึกอัปเดต</button></form></article><?php endforeach; endif; ?></section>
<?php page_foot(); ?>
